import { useCapabilities } from 'pixelkit';

function ProFeatures() {
  const caps = useCapabilities();
  return (
    <View>
      <Text>{caps.modelName} · API {caps.androidApiLevel} · {caps.verification}</Text>
      {caps.hasHiLight && <HiLightCard />}
      {caps.hasUWB && <UWBCard />}
    </View>
  );
}
